import java.util.*;

public class Main {
    record Point(int x, int y) {}

    public static void main(String[] args) {
        List<Point> pts = List.of(new Point(2, 1), new Point(1, 5));
        pts.stream()
           .sorted(Comparator.comparingInt(Point::x))
           .forEach(System.out::println);   // Point[x=1, y=5] then Point[x=2, y=1]
    }
}

async function getJson(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error("HTTP " + res.status);
  return res.json();
}

getJson("https://example.com/api/items")
  .then((items) => console.log(items.length))
